class Sailing_calculate_tide(API_base):
    """
    Calculates the tide levels for a given location and time range to assist in navigation planning.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_location", "p_time_range"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_location = params.get('p_location', None)
        if p_location is None:
            return self.handle_error(f"Required parameter 'p_location' is missing", 400)
        is_valid, error = self.validate_type(p_location, 'p_location', str)
        if not is_valid:
            return error
        
        p_time_range = params.get('p_time_range', None)
        if p_time_range is not None:
            is_valid, error = self.validate_type(p_time_range, 'p_time_range', dict)
            if not is_valid:
                return error
        
        if p_time_range is not None:

            p_start_time = p_time_range.get('p_start_time', None)
            if p_start_time is None:
                return self.handle_error(f"Required parameter 'p_start_time' is missing", 400)
            is_valid, error = self.validate_type(p_start_time, 'p_start_time', str)
            if not is_valid:
                return error
            
            if p_start_time is not None and p_start_time not in ["Morning", "Afternoon", "Evening"]:
                return self.handle_error(f"Parameter 'p_start_time' not in valid enum", 400)
            
            p_end_time = p_time_range.get('p_end_time', None)
            if p_end_time is None:
                return self.handle_error(f"Required parameter 'p_end_time' is missing", 400)
            is_valid, error = self.validate_type(p_end_time, 'p_end_time', str)
            if not is_valid:
                return error
            
            if p_end_time is not None and p_end_time not in ["Morning", "Afternoon", "Evening"]:
                return self.handle_error(f"Parameter 'p_end_time' not in valid enum", 400)
            
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Sailing_calculate_tide",
                "p_location": p_location,
                "p_time_range": p_time_range
            }
        }

