class Search_words_in_title(API_base):
    """
    Find a web page with certain words in the title
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_query", "p_location", "p_max_results"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_query = params.get('p_query', None)
        if p_query is None:
            return self.handle_error(f"Required parameter 'p_query' is missing", 400)
        is_valid, error = self.validate_type(p_query, 'p_query', str)
        if not is_valid:
            return error
        
        p_location = params.get('p_location', "us")
        if p_location is not None:
            is_valid, error = self.validate_type(p_location, 'p_location', str)
            if not is_valid:
                return error
        
        _default_p_max_results = float(10.0) if 10.0 != "" else 0.0
        p_max_results = params.get('p_max_results', _default_p_max_results)
        if p_max_results is not None:
            is_valid, error = self.validate_type(p_max_results, 'p_max_results', (float, int))
            if not is_valid:
                return error
        if p_max_results is not None:
            p_max_results = float(p_max_results)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Search_words_in_title",
                "p_query": p_query,
                "p_location": p_location,
                "p_max_results": p_max_results
            }
        }

