class Radio_signal_analysis(API_base):
    """
    Analyzes the quality and strength of radio signals over specified time periods.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_frequency_range", "p_time_period", "p_analysis_depth"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_frequency_range = params.get('p_frequency_range', None)
        if p_frequency_range is None:
            return self.handle_error(f"Required parameter 'p_frequency_range' is missing", 400)
        is_valid, error = self.validate_type(p_frequency_range, 'p_frequency_range', dict)
        if not is_valid:
            return error
        

        p_min_frequency = p_frequency_range.get('p_min_frequency', None)
        if p_min_frequency is None:
            return self.handle_error(f"Required parameter 'p_min_frequency' is missing", 400)
        is_valid, error = self.validate_type(p_min_frequency, 'p_min_frequency', (float, int))
        if not is_valid:
            return error
        if p_min_frequency is not None:
            p_min_frequency = float(p_min_frequency)
        
        p_max_frequency = p_frequency_range.get('p_max_frequency', None)
        if p_max_frequency is None:
            return self.handle_error(f"Required parameter 'p_max_frequency' is missing", 400)
        is_valid, error = self.validate_type(p_max_frequency, 'p_max_frequency', (float, int))
        if not is_valid:
            return error
        if p_max_frequency is not None:
            p_max_frequency = float(p_max_frequency)
        
        p_time_period = params.get('p_time_period', None)
        if p_time_period is None:
            return self.handle_error(f"Required parameter 'p_time_period' is missing", 400)
        is_valid, error = self.validate_type(p_time_period, 'p_time_period', dict)
        if not is_valid:
            return error
        

        p_start_time = p_time_period.get('p_start_time', None)
        if p_start_time is None:
            return self.handle_error(f"Required parameter 'p_start_time' is missing", 400)
        is_valid, error = self.validate_type(p_start_time, 'p_start_time', str)
        if not is_valid:
            return error
        
        p_end_time = p_time_period.get('p_end_time', None)
        if p_end_time is None:
            return self.handle_error(f"Required parameter 'p_end_time' is missing", 400)
        is_valid, error = self.validate_type(p_end_time, 'p_end_time', str)
        if not is_valid:
            return error
        
        p_analysis_depth = params.get('p_analysis_depth', None)
        if p_analysis_depth is not None:
            is_valid, error = self.validate_type(p_analysis_depth, 'p_analysis_depth', str)
            if not is_valid:
                return error
        
        if p_analysis_depth is not None and p_analysis_depth not in ["basic", "detailed", "expert"]:
            return self.handle_error(f"Parameter 'p_analysis_depth' not in valid enum", 400)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Radio_signal_analysis",
                "p_frequency_range": p_frequency_range,
                "p_time_period": p_time_period,
                "p_analysis_depth": p_analysis_depth
            }
        }

